module webcrypto

import encoding.hex
import webidl

fn test_aes_gcm_native_source_fixtures_all_key_tag_and_iv_lengths() {
	subtle := SubtleCrypto.create()
	for vector in aes_gcm_source_vectors {
		key := subtle.import_key(.raw_secret, hex.decode(vector.key_hex)!, 'AES-GCM', false, [
			.encrypt,
			.decrypt,
		], '')!
		input := hex.decode(vector.input_hex)!
		for with_aad in [false, true] {
			aad := if with_aad { hex.decode(vector.aad_hex)! } else { []u8{} }
			tag := if with_aad {
				hex.decode(vector.tag_hex)!
			} else {
				hex.decode(vector.empty_aad_tag_hex)!
			}
			for bits in [u8(32), 64, 96, 104, 112, 120, 128] {
				params := AesGcmParams{
					iv:              hex.decode(vector.iv_hex)!
					additional_data: aad
					tag_length:      bits
				}
				mut expected := hex.decode(vector.output_hex)!
				expected << tag[..int(bits / 8)]
				assert subtle.encrypt(params, key, input)! == expected
				assert subtle.decrypt(params, key, expected)! == input
				mut corrupt := expected.clone()
				corrupt[corrupt.len - 1] ^= 1
				if _ := subtle.decrypt(params, key, corrupt) {
					assert false
				} else {
					assert err.msg() == 'OperationError: Decryption failed'
				}
			}
		}
	}
}

fn test_aes_gcm_source_error_order_and_native_empty_input() {
	key := CryptoKey.create(.secret, false, KeyAlgorithm{}, [], [])
	for bits in [u8(0), 1, 31, 65, 127, 129, 255] {
		params := AesGcmParams{
			tag_length: bits
		}
		if _ := AesGcm.create().encrypt(params, key, []) {
			assert false
		} else {
			assert err.msg() == 'OperationError: Invalid tag length'
		}
		if _ := AesGcm.create().decrypt(params, key, []) {
			assert false
		} else {
			assert err.msg() == 'OperationError: Invalid tag length'
		}
	}
	if _ := AesGcm.create().decrypt(AesGcmParams{}, key, []) {
		assert false
	} else {
		assert err.msg() == 'OperationError: Invalid ciphertext length'
	}
	if _ := AesGcm.create().encrypt(AesGcmParams{ iv: []u8{len: 12} }, key, []) {
		assert false
	} else {
		assert err.msg() == 'OperationError: Encryption failed'
	}
	valid := SubtleCrypto.create().import_key(.raw, []u8{len: 16}, 'AES-GCM', false, [
		.encrypt,
		.decrypt,
	], '')!
	if _ := AesGcm.create().encrypt(AesGcmParams{}, valid, []) {
		assert false
	} else {
		assert err.msg() == 'OperationError: Encryption failed'
	}
	if _ := AesGcm.create().decrypt(AesGcmParams{}, valid, []u8{len: 16}) {
		assert false
	} else {
		assert err.msg() == 'OperationError: Decryption failed'
	}
	params := AesGcmParams{
		iv: []u8{len: 12}
	}
	output := AesGcm.create().encrypt(params, valid, [])!
	assert output.hex() == '58e2fccefa7e3061367f1d57a4e7455a'
	assert AesGcm.create().decrypt(params, valid, output)!.len == 0
}

@[heap]
struct AesGcmBindingHost {
mut:
	work   []fn ()
	settle []fn ()
}

fn test_aes_gcm_async_native_operation_copies_iv_aad_and_tag_length() {
	mut host := &AesGcmBindingHost{}
	subtle := SubtleCrypto.create()
	binding := SubtleCryptoBinding.create(subtle, webidl.PromiseContext{}, fn [mut host] (task fn ()) {
		host.work << task
	}, fn [mut host] (task fn ()) {
		host.settle << task
	})
	vector := aes_gcm_source_vectors.last()
	key := subtle.import_key(.raw, hex.decode(vector.key_hex)!, 'AES-GCM', false, [
		.encrypt,
	], '')!
	mut iv := webidl.BufferSource.array_buffer(hex.decode(vector.iv_hex)!)
	mut aad := webidl.BufferSource.array_buffer(hex.decode(vector.aad_hex)!)
	mut input := webidl.BufferSource.array_buffer(hex.decode(vector.input_hex)!)
	mut members := {
		'name':           webidl.string_value('AES-GCM')
		'iv':             webidl.buffer_source_value(iv)
		'additionalData': webidl.buffer_source_value(aad)
		'tagLength':      webidl.number_value(104)
	}
	promise := binding.encrypt(webidl.object_value(members), key, input)
	iv.write([]u8{len: int(iv.byte_length())}, 0)!
	aad.write([]u8{len: int(aad.byte_length())}, 0)!
	input.write([]u8{len: int(input.byte_length())}, 0)!
	members['tagLength'] = webidl.number_value(0)
	host.work[0]()
	assert promise.state == .pending
	host.settle[0]()
	assert promise.state == .fulfilled
	assert webidl.get_buffer_source_copy(promise.result.buffer_value or { panic('bytes') }).hex() ==
		vector.output_hex + vector.tag_hex[..26]
}

struct AesGcmSourceVector {
	key_hex           string
	iv_hex            string
	input_hex         string
	aad_hex           string
	output_hex        string
	tag_hex           string
	empty_aad_tag_hex string
}

